import {normalize,fresh,completed,access,canEnter,enter,award,restore,achievements} from './core.mjs';
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog'),toast=document.querySelector('#toast');
const KEY='so-viet-player-v1';let data,state,region,tab='landmark',query='',view='book',zoom=1,pan=[0,0],selectedStart='',startQuery='',quiz=null,toastTimer,storageWarning=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3z"/><path d="M9 3v15M15 6v15"/>',food:'<path d="M3 11h18c0 6-4 9-9 9s-9-3-9-9ZM6 22h12M14 3l-4 5M20 3l-7 5"/>',trophy:'<path d="M7 3h10v7a5 5 0 0 1-10 0zM12 15v6M8 21h8M7 5H3v3a4 4 0 0 0 4 4m10-7h4v3a4 4 0 0 1-4 4"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',check:'<path d="m5 12 5 5L20 6"/>',arrow:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m15 5-7 7 7 7"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/>',book:'<path d="M12 5C8 2 3 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-4-2-7-1-10 1Zm0 0v16"/>',plus:'<path d="M5 12h14M12 5v14"/>',minus:'<path d="M5 12h14"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2"/>'};
function icon(id){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[id]||icons.spark}</svg>`;}
function notify(s){toast.textContent=s;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),4500);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{if(!storageWarning){storageWarning=true;notify('Trình duyệt không lưu được tiến độ. Hãy xuất bản sao trong Hồ sơ.');}}}
function byRegion(id){return data.regions.find(r=>r.id===id);}
function chapter(id){return data.chapters.find(c=>c.id===id);}
function card(id){return data.cards.find(c=>c.id===id);}
function earned(c){return state?.earned.includes(c.id)??false;}
function art(c,cls=''){return c.art!=null?`<div class="art atlas ${cls}" style="--ax:${c.art%4};--ay:${Math.floor(c.art/4)}" role="img" aria-label="${esc(earned(c)?'Tranh minh họa '+c.name:'Hình thẻ chưa mở')}"></div>`:`<div class="art placeholder ${c.type==='food'?'food-art':''} ${cls}" aria-label="Minh họa biểu tượng" role="img">${icon(c.type==='food'?'food':'map')}<span>Minh họa</span></div>`;}
function header(){return `<header class="topbar"><a href="#" class="brand" data-action="home">${icon('book')}<span>Sổ Việt<small>ĐI ĐỂ HIỂU · CHƠI ĐỂ NHỚ</small></span></a><div class="top-right"><span class="edition">BẢN CHƠI THỬ</span>${state?`<button class="profile" data-action="profile">${icon('spark')}<span>${esc(state.name)}</span><b>${state.earned.length}</b></button>`:''}</div></header>`;}
function startScreen(){
 const rs=data.regions.filter(r=>normalize(r.name+' '+chapter(r.chapter).name).includes(normalize(startQuery)));
 app.innerHTML=header()+`<main id="main" class="start-layout"><section class="welcome"><span class="eyebrow">MỘT CUỐN SỔ · NGÀN ĐIỀU THÚ VỊ</span><h1>Việt Nam mình,<br><em>đi đâu trước?</em></h1><p>Mỗi vùng đất là một trang chuyện.<br>Giải câu đố, gom thẻ xinh, mở những chân trời mới.</p><div class="mini-badges"><span>34 chapter</span><span>63 vùng khám phá</span><span>${data.cards.length} thẻ</span></div><div class="welcome-art"><div class="postcard one">${art({...data.cards.find(c=>c.art===6)})}<b>Những miền di sản</b></div><div class="postcard two">${art({...data.cards.find(c=>c.art===11)})}<b>Hương vị quê nhà</b></div><span class="art-spark">✦</span></div><p class="local-note">${icon('lock')} Hồ sơ lưu trên trình duyệt của bạn.</p></section><section class="start-panel"><div class="section-kicker">01 / BẮT ĐẦU HÀNH TRÌNH</div><h2>Chọn nơi bạn khởi hành</h2><p>Chọn một trong 63 vùng. Bạn có thể bắt đầu ở bất cứ đâu.</p><label class="field-label" for="player-name">Tên nhà thám hiểm</label><input id="player-name" maxlength="40" placeholder="Bạn muốn được gọi là gì?" autocomplete="nickname"><label class="searchbox">${icon('search')}<input id="start-search" type="search" placeholder="Tìm tỉnh, thành…" value="${esc(startQuery)}" aria-label="Tìm vùng xuất phát"></label><div class="region-picker" role="group" aria-label="63 vùng xuất phát">${rs.map(r=>`<button class="region-choice ${selectedStart===r.id?'selected':''}" data-start="${r.id}" aria-pressed="${selectedStart===r.id}"><span>${esc(r.name)}</span><small>${esc(chapter(r.chapter).name)}</small>${selectedStart===r.id?icon('check'):''}</button>`).join('')||'<p class="empty">Không tìm thấy vùng phù hợp.</p>'}</div><div class="start-bottom"><span id="selected-label">${selectedStart?'Khởi hành từ '+esc(byRegion(selectedStart).name):'Chọn một vùng để tiếp tục'}</span><button id="begin" class="primary" ${selectedStart?'':'disabled'}>Mở sổ hành trình ${icon('arrow')}</button></div></section></main><footer class="footer">Một hành trình nhỏ, một Việt Nam thật gần. <button data-action="about">Về bản chơi thử</button></footer>`;
 document.querySelector('#start-search').oninput=e=>{const name=document.querySelector('#player-name').value;const pos=e.target.selectionStart;startQuery=e.target.value;startScreen();document.querySelector('#player-name').value=name;const input=document.querySelector('#start-search');input.focus();try{input.setSelectionRange(pos,pos);}catch{}};
 document.querySelectorAll('[data-start]').forEach(el=>el.onclick=()=>{const name=document.querySelector('#player-name').value;selectedStart=el.dataset.start;startScreen();document.querySelector('#player-name').value=name;});
 document.querySelector('#begin').onclick=()=>{const input=document.querySelector('#player-name');if(!input.value.trim()){input.focus();notify('Nhập tên nhà thám hiểm để mở sổ nhé.');return;}state=fresh(input.value,selectedStart);region=selectedStart;save();render();notify('Chào '+state.name+'! Chọn một thẻ để bắt đầu khám phá.');};bindGlobal();
}
// Equirectangular projection with a fixed latitude correction for consistent map/pin alignment.
const project=([lon,lat])=>[lon*.94,-lat];
function rings(g){return g.type==='Polygon'?g.coordinates:g.coordinates.flat();}
function path(g){return rings(g).map(r=>'M'+r.map(x=>project(x).map(n=>n.toFixed(4)).join(',')).join('L')+'Z').join('');}
function bounds(features){const ps=features.flatMap(f=>rings(f.geometry).flat().map(project));let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;for(const [x,y]of ps){minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);}return [minX,minY,maxX-minX,maxY-minY];}
function mapSvg(global=false,opts={}){
 const ch=chapter(byRegion(region).chapter),features=global?data.chapters:data.regions.filter(r=>r.chapter===ch.id),bb=bounds(features),pad=Math.max(bb[2],bb[3])*.09;
 const scale=global?zoom:1;const w=(bb[2]+pad*2)/scale,h=(bb[3]+pad*2)/scale;const vb=[bb[0]-pad+(bb[2]+pad*2-w)/2+pan[0],bb[1]-pad+(bb[3]+pad*2-h)/2+pan[1],w,h];
 const a=access(data,state);const stroke=Math.max(w,h)*.004,fs=Math.max(w,h)*.032;
 const shapes=features.map(f=>{let available=global?a.chapters.has(f.id):a.regions.has(f.id),done=global?f.regions.every(id=>completed(data,state,id)):completed(data,state,f.id);const active=global?f.id===ch.id:f.id===region;return `<path class="province ${available?'available':'locked'} ${active?'active':''} ${done?'done':''}" d="${path(f.geometry)}" fill-rule="evenodd" style="stroke-width:${stroke}" data-${global?'chapter':'region'}="${f.id}" tabindex="0" role="button" aria-label="${esc(f.name)}${available?'':' · Chưa mở'}"><title>${esc(f.name)}${done?' · Đã hoàn thành':available?' · Có thể khám phá':' · Chưa mở'}</title></path>`;}).join('');
 const labels=!global?features.map(f=>{const [x,y]=project(f.center);return `<text class="region-label" x="${x}" y="${y}" font-size="${fs}" text-anchor="middle" pointer-events="none">${esc(f.name)}</text>${a.regions.has(f.id)?'':`<text x="${x}" y="${y-fs*1.1}" font-size="${fs*1.1}" text-anchor="middle" fill="#6d7e84" pointer-events="none">▣</text>`}`;}).join(''):'';
 const pins=!global?data.cards.filter(c=>c.type==='landmark'&&c.coordinates&&earned(c)&&features.some(f=>f.id===c.region)).map(c=>{const [x,y]=project(c.coordinates);return `<g class="map-pin" data-card="${c.id}" tabindex="0" role="button" aria-label="${esc(c.name)}"><title>${esc(c.name)}</title><circle cx="${x}" cy="${y}" r="${fs*.47}" fill="#f7f0dc" stroke="#087a84" stroke-width="${stroke}"/><circle cx="${x}" cy="${y}" r="${fs*.22}" fill="#ff9971"/></g>`;}).join(''):'';
 return `<svg class="geographic-map ${global?'national':''}" viewBox="${vb.join(' ')}" role="group" aria-label="${global?'Bản đồ 34 tỉnh thành':'Bản đồ chapter '+esc(ch.name)}">${shapes}${labels}${pins}</svg>`;
}
function stats(){return `${state.earned.length} thẻ · ${data.regions.filter(r=>completed(data,state,r.id)).length}/63 vùng`;}
function render(){if(!state){startScreen();return;}if(view==='world'){worldScreen();return;}bookScreen();}
function cardRow(c){const unlocked=earned(c);return `<button class="card-row ${unlocked?'unlocked':'sealed'}" data-card="${c.id}" aria-label="${unlocked?esc(c.name):'Thẻ chưa mở · Bắt đầu thử thách'}"><div class="thumb">${art(c,unlocked?'':'blurred')}${unlocked?'':`<span class="lock-overlay">${icon('lock')}</span>`}</div><span class="card-copy"><span class="card-title">${unlocked?esc(c.name):'Miền đất bí ẩn'}</span>${unlocked&&c.heritage?`<span class="heritage-tag">${icon('spark')} Di sản thế giới · ${c.heritage.year}</span>`:''}<span class="card-intro">${unlocked?esc(c.intro):'Một câu đố, một điều mới. Bạn đã sẵn sàng?'}</span><span class="card-status">${unlocked?'Đã thu thập':'Khám phá '+icon('arrow')}</span></span><span class="card-end">${icon(unlocked?'check':'lock')}</span></button>`;}
function achievementList(){return `<div class="collection-hint">Dấu ấn của bạn trên khắp Việt Nam</div>${achievements(data,state).map(a=>`<article class="achievement ${a.current>=a.total?'achieved':''}"><div class="medal">${icon(a.icon)}</div><div><h3>${esc(a.name)}</h3><p>${esc(a.intro)}</p><progress max="${a.total}" value="${a.current}" aria-label="${esc(a.name)}"></progress><small>${a.current}/${a.total}${a.current>=a.total?' · Đã đạt':''}</small></div></article>`).join('')}<div class="heritage-section"><h3>Di sản sống</h3><p>Khám phá những thực hành văn hóa được UNESCO ghi danh.</p>${data.heritages.map(h=>`<button class="heritage-link" data-heritage="${h.id}">${icon('spark')}<span>${esc(h.name)}</span>${icon('arrow')}</button>`).join('')}</div>`;}
function bookScreen(){
 const r=byRegion(region),ch=chapter(r.chapter),a=access(data,state);const type=tab==='food'?'food':'landmark';const cs=r.cards.map(card).filter(c=>c.type===type);let content;
 if(tab==='trophy')content=achievementList();else if(tab==='search'){const matches=query.trim()?data.cards.filter(c=>normalize(c.name+' '+byRegion(c.region).name).includes(normalize(query))).slice(0,60):[];content=`<label class="searchbox collection-search">${icon('search')}<input id="collection-search" type="search" value="${esc(query)}" placeholder="Tên địa điểm hoặc món ăn…" aria-label="Tìm địa điểm hoặc món ăn"></label><p class="collection-hint">Tìm trên cả 63 vùng · Không phân biệt dấu tiếng Việt</p><div id="search-results">${query.trim()?matches.map(c=>{const allowed=a.regions.has(c.region);return `<button class="search-result" data-result="${c.id}">${icon(c.type==='food'?'food':'map')}<span><b>${esc(c.name)}</b><small>${esc(byRegion(c.region).name)} · ${allowed?'Có thể khám phá':'Vùng chưa mở'}</small></span>${icon(allowed?'arrow':'lock')}</button>`;}).join('')||'<p class="empty">Chưa tìm thấy. Thử tên khác nhé.</p>':'<div class="empty search-empty">'+icon('search')+'<h3>Bạn đang tìm điều gì?</h3><p>Thử “bánh mì”, “chùa Keo” hoặc “Hà Nội”.</p></div>'}</div>`;}else content=`<p class="collection-hint">${type==='landmark'?'Những nơi đáng đến, những chuyện đáng nhớ.':'Hương vị đặc trưng, mỗi miền một nét riêng.'}</p>${cs.map(cardRow).join('')}`;
 app.innerHTML=header()+`<main id="main" class="game-shell"><div class="journey-top"><span>${icon('pin')} HÀNH TRÌNH CỦA ${esc(state.name.toUpperCase())}</span><button class="text-button" data-action="guide">Cách chơi ${icon('book')}</button></div><section class="book"><div class="book-spine"></div><section class="page map-page"><div class="page-corners"></div><div class="page-top"><button class="all-button" data-action="world">${icon('map')} Tất cả</button><span class="chapter-tag">CHAPTER ${String(data.chapters.indexOf(ch)+1).padStart(2,'0')} / 34</span></div><h1>${esc(ch.name)}</h1><div class="title-rule"><span></span>${icon('spark')}<span></span></div><div class="chapter-map">${mapSvg()}</div><div class="map-key"><span><i></i> Đang khám phá</span><span><i class="grey"></i> Chưa mở</span></div><div class="region-switcher">${ch.regions.map(id=>`<button data-switch="${id}" class="${id===region?'current':''}" ${canEnter(data,state,id)?'':'disabled'}>${a.regions.has(id)?completed(data,state,id)?icon('check'):icon('pin'):icon('lock')}${esc(byRegion(id).name)}</button>`).join('')}</div><div class="map-footer"><span>${icon('book')} ${esc(r.name)}</span><b>${r.cards.filter(id=>state.earned.includes(id)).length}/${r.cards.length} thẻ</b></div><span class="page-number">${String(data.chapters.indexOf(ch)*2+1).padStart(2,'0')}</span></section><section class="page collection-page"><nav class="bookmark-tabs" aria-label="Bộ sưu tập"><button data-tab="landmark" class="bookmark map-tab ${tab==='landmark'?'selected':''}" aria-label="Địa danh" aria-pressed="${tab==='landmark'}" title="Địa danh">${icon('map')}</button><button data-tab="food" class="bookmark food-tab ${tab==='food'?'selected':''}" aria-label="Món ăn" aria-pressed="${tab==='food'}" title="Món ăn">${icon('food')}</button><button data-tab="trophy" class="bookmark trophy-tab ${tab==='trophy'?'selected':''}" aria-label="Thành tựu" aria-pressed="${tab==='trophy'}" title="Thành tựu">${icon('trophy')}</button><button data-tab="search" class="bookmark search-tab ${tab==='search'?'selected':''}" aria-label="Tìm kiếm" aria-pressed="${tab==='search'}" title="Tìm địa điểm hoặc món ăn">${icon('search')}</button></nav><h2>Bộ sưu tập</h2><div class="collection-subtitle">${tab==='trophy'?'Thành tựu hành trình':tab==='search'?'Tìm điều bạn yêu':esc(r.name)}<span>${tab==='landmark'?'ĐỊA DANH':tab==='food'?'MÓN ĂN':tab==='trophy'?'DẤU ẤN KHÁM PHÁ':'63 VÙNG · MỘT HÀNH TRÌNH'}</span></div><div class="collection-scroll">${content}</div><div class="collection-bottom"><span>${tab==='landmark'?icon('map'):tab==='food'?icon('food'):icon('spark')}${tab==='trophy'?'Mỗi chuyến đi, một dấu ấn':tab==='search'?'Tìm kiếm toàn bộ bộ sưu tập':`${cs.filter(earned).length}/${cs.length} ${type==='food'?'đặc sản':'địa danh'} đã khám phá`}</span><span class="page-number">${String(data.chapters.indexOf(ch)*2+2).padStart(2,'0')}</span></div></section></section><div class="below-book"><span>${icon('check')} Tự động lưu trên trình duyệt</span><span>${stats()}</span></div></main><footer class="footer">63 vùng đất. Hành trình của riêng bạn.<button data-action="about">Nguồn & thông tin bản thử</button></footer>`;
 bindGlobal();bindMap();document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();if(tab==='search')document.querySelector('#collection-search').focus();});
 document.querySelectorAll('[data-switch]').forEach(b=>b.onclick=()=>navigate(b.dataset.switch));document.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>openCard(b.dataset.card));
 document.querySelectorAll('[data-heritage]').forEach(b=>b.onclick=()=>openHeritage(b.dataset.heritage));document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{const c=card(b.dataset.result);if(!canEnter(data,state,c.region)){notify('Hoàn thành các vùng trước để mở đường tới '+byRegion(c.region).name+'.');return;}navigate(c.region);openCard(c.id);});
 const search=document.querySelector('#collection-search');if(search)search.oninput=e=>{const pos=e.target.selectionStart;query=e.target.value;bookScreen();const s=document.querySelector('#collection-search');s.focus();try{s.setSelectionRange(pos,pos);}catch{}};
}
function navigate(id){if(!enter(data,state,id)){notify('Vùng này chưa mở. Thu thập đủ 3 thẻ tại vùng đang khám phá nhé.');return;}region=id;state.lastRegion=id;tab='landmark';view='book';pan=[0,0];zoom=1;save();render();}
function worldScreen(){
 const a=access(data,state);app.innerHTML=header()+`<main id="main" class="world-layout"><section class="world-map-panel"><div class="world-heading"><button class="text-button" data-action="book">${icon('back')} Về sổ</button><span>34 CHAPTER · 63 VÙNG KHÁM PHÁ</span></div><h1>Việt Nam, mình đi tiếp nhé!</h1><p>Chọn một chapter để xem các vùng. Kéo bản đồ hoặc dùng nút phóng to.</p><div class="world-map">${mapSvg(true)}<div class="zoom-controls"><button data-zoom="in" aria-label="Phóng to">${icon('plus')}</button><button data-zoom="out" aria-label="Thu nhỏ">${icon('minus')}</button><button data-zoom="reset" aria-label="Đặt lại bản đồ">${icon('map')}</button></div><span class="sea-label">BIỂN ĐÔNG</span></div><p class="map-caption">Bản đồ hành chính được giản lược để hiển thị trong game. Các đảo xa bờ xem ở dữ liệu nguồn.</p></section><aside class="chapter-directory"><h2>Những trang tiếp theo</h2><p>${a.chapters.size}/34 chapter có thể bắt đầu</p><label class="searchbox">${icon('search')}<input id="chapter-search" placeholder="Tìm chapter…" aria-label="Tìm chapter"></label><div class="chapter-list">${data.chapters.map(c=>`<button data-chapter="${c.id}" data-name="${normalize(c.name)}" class="chapter-item ${a.chapters.has(c.id)?'':'locked'}"><span class="chapter-icon">${icon(a.chapters.has(c.id)?'map':'lock')}</span><span><b>${esc(c.name)}</b><small>${c.regions.length} vùng · ${c.regions.filter(id=>completed(data,state,id)).length} hoàn thành</small></span>${icon('arrow')}</button>`).join('')}</div></aside></main>`;bindGlobal();bindMap();document.querySelector('#chapter-search').oninput=e=>document.querySelectorAll('.chapter-item').forEach(b=>b.hidden=!b.dataset.name.includes(normalize(e.target.value)));document.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{if(b.dataset.zoom==='reset'){zoom=1;pan=[0,0];}else zoom=Math.max(1,Math.min(8,zoom*(b.dataset.zoom==='in'?1.5:1/1.5)));worldScreen();});
 const svg=document.querySelector('.national');let drag=null,moved=false;
 svg.onpointerdown=e=>{if(e.pointerType==='touch'&&e.isPrimary===false)return;drag={x:e.clientX,y:e.clientY,pan:[...pan],vb:svg.viewBox.baseVal.width};moved=false;};
 svg.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>8)moved=true;if(moved){pan=[drag.pan[0]-dx/svg.clientWidth*drag.vb,drag.pan[1]-dy/svg.clientWidth*drag.vb];const b=svg.viewBox.baseVal;const deltaX=pan[0]-drag.pan[0],deltaY=pan[1]-drag.pan[1];const base=bounds(data.chapters),pad=Math.max(base[2],base[3])*.09;svg.setAttribute('viewBox',[base[0]-pad+(base[2]+2*pad-b.width)/2+pan[0],base[1]-pad+(base[3]+2*pad-b.height)/2+pan[1],b.width,b.height].join(' '));}};
 svg.onpointerup=()=>{drag=null;if(moved){svg.dataset.dragged='true';setTimeout(()=>delete svg.dataset.dragged,100);}};svg.onpointerleave=()=>{drag=null;};
}
function bindMap(){document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{if(document.querySelector('.national')?.dataset.dragged)return;openChapter(b.dataset.chapter);});document.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>navigate(b.dataset.region));document.querySelectorAll('.geographic-map [role=button]').forEach(b=>b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();b.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});}
function openChapter(id){const c=chapter(id),a=access(data,state);showDialog(`<span class="eyebrow">CHỌN VÙNG KHÁM PHÁ</span><h2>${esc(c.name)}</h2><p>${a.chapters.has(id)?'Chọn nơi bắt đầu hoặc tiếp tục hành trình.':'Hoàn thành một chapter tiếp giáp để mở đường đến đây.'}</p><div class="chapter-options">${c.regions.map(rid=>`<button data-enter="${rid}" ${canEnter(data,state,rid)?'':'disabled'}>${icon(canEnter(data,state,rid)?'map':'lock')}<span>${esc(byRegion(rid).name)}<small>${completed(data,state,rid)?'Đã hoàn thành':a.regions.has(rid)?'Đang khám phá':canEnter(data,state,rid)?'Có thể chọn làm điểm vào':'Chưa mở'}</small></span>${icon('arrow')}</button>`).join('')}</div>`);document.querySelectorAll('[data-enter]').forEach(b=>b.onclick=()=>{dialog.close();navigate(b.dataset.enter);});}
function showDialog(html){dialog.innerHTML=`<button class="dialog-close" aria-label="Đóng">${icon('close')}</button><div class="dialog-content">${html}</div>`;if(!dialog.open)dialog.showModal();dialog.querySelector('.dialog-close').onclick=()=>dialog.close();}
function openCard(id){const c=card(id);if(!earned(c)){if(!access(data,state).regions.has(c.region)){notify('Vùng này chưa mở.');return;}challengePicker(c);return;}
 showDialog(`<div class="detail-image">${art(c)}</div><span class="eyebrow">${c.type==='food'?'HƯƠNG VỊ QUÊ NHÀ':'DẤU CHÂN KHÁM PHÁ'} · ${esc(byRegion(c.region).name)}</span><h2>${esc(c.name)}</h2>${c.heritage?`<div class="heritage-tag">${icon('spark')} ${esc(c.heritage.kind)} · ${c.heritage.year}</div><p class="heritage-context">Thuộc: ${esc(c.heritage.name)}. Danh hiệu áp dụng cho di sản được ghi danh.</p>`:''}<p class="detail-intro">${esc(c.intro)}</p><div class="detail-sources"><a href="${esc(c.source)}" target="_blank" rel="noopener noreferrer">${esc(c.sourceLabel)} ↗</a><span>${c.art!=null?'Tranh minh họa hoạt hình':'Hình biểu tượng tạm thời'}</span></div>${c.type==='landmark'&&c.coordinates?`<a class="map-source" href="https://www.google.com/maps/search/?api=1&query=${c.coordinates[1]},${c.coordinates[0]}" target="_blank" rel="noopener noreferrer">Xem vị trí trên Google Maps ↗</a>`:''}<button class="primary wide" id="practice">Chơi lại thử thách ${icon('spark')}</button>`);document.querySelector('#practice').onclick=()=>challengePicker(c);
}
function challengePicker(c){showDialog(`<span class="eyebrow">MỘT THẺ MỚI ĐANG CHỜ BẠN</span><h2>Khám phá theo cách của bạn</h2><p>Chọn một thử thách. Trả lời đúng để nhận thẻ; trả lời sai có thể thử lại.</p><div class="challenge-options"><button data-mode="clue">${icon('book')}<span><b>Giải mã văn hóa</b><small>Đọc mô tả, tìm tên phù hợp</small></span>${icon('arrow')}</button><button data-mode="geo">${icon('map')}<span><b>Nhà thám hiểm địa lý</b><small>Chọn vùng trên bản đồ Việt Nam</small></span>${icon('arrow')}</button>${c.art!=null?`<button data-mode="image">${icon('search')}<span><b>Nhận diện hình ảnh</b><small>Đoán qua tranh bị che một phần</small></span>${icon('arrow')}</button>`:''}</div>`);document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>startQuiz(c,b.dataset.mode));}
function shuffled(xs){return xs.map(x=>({x,k:Math.random()})).sort((a,b)=>a.k-b.k).map(a=>a.x);}
function startQuiz(c,mode){
 const correct=mode==='geo'?c.region:c.id;const distractors=mode==='geo'?shuffled(data.regions.filter(r=>r.id!==c.region)).slice(0,3).map(r=>r.id):shuffled(data.cards.filter(x=>x.type===c.type&&x.id!==c.id)).slice(0,3).map(x=>x.id);const options=shuffled([correct,...distractors]);quiz={card:c.id,mode,correct,options,done:false};
 const question=mode==='image'?'Bạn nhận ra hình ảnh nào?':mode==='geo'?'Địa điểm hoặc đặc sản này thuộc vùng nào?':'Mô tả này nhắc đến điều gì?';
 showDialog(`<span class="eyebrow">${mode==='image'?'NHẬN DIỆN HÌNH ẢNH':mode==='geo'?'NHÀ THÁM HIỂM ĐỊA LÝ':'GIẢI MÃ VĂN HÓA'}</span><h2>${question}</h2>${mode==='image'?`<div class="quiz-image">${art(c)}<div class="image-mask"></div></div>`:`<div class="clue">${mode==='geo'?`<b>${esc(c.name)}</b><br>`:''}${esc(c.intro)}</div>`}${mode==='geo'?quizMap(options):`<div class="answers">${options.map((id,i)=>`<button data-answer="${id}"><span>${'ABCD'[i]}</span>${esc(card(id).name)}</button>`).join('')}</div>`}<div id="answer-feedback" role="status" aria-live="polite"></div>`);
 document.querySelectorAll('[data-answer]').forEach(b=>{b.onclick=()=>answer(b.dataset.answer,b);if(b.tagName==='path')b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();answer(b.dataset.answer,b);}};});
}
function quizMap(options){const fs=data.regions,bb=bounds(fs),pad=.3;return `<div class="geo-quiz"><svg viewBox="${[bb[0]-pad,bb[1]-pad,bb[2]+2*pad,bb[3]+2*pad].join(' ')}" aria-label="Chọn vùng đúng trên bản đồ">${fs.map(r=>`<path d="${path(r.geometry)}" fill-rule="evenodd" class="quiz-region ${options.includes(r.id)?'option':''}" ${options.includes(r.id)?`data-answer="${r.id}" tabindex="0" role="button" aria-label="${esc(r.name)}"`:''}><title>${esc(r.name)}</title></path>`).join('')}</svg><div class="answers">${options.map((id,i)=>`<button data-answer="${id}"><span>${'ABCD'[i]}</span>${esc(byRegion(id).name)}</button>`).join('')}</div></div>`;}
function answer(id,button){if(!quiz||quiz.done)return;const feedback=document.querySelector('#answer-feedback');if(id!==quiz.correct){button.classList.add('wrong');button.setAttribute('aria-disabled','true');feedback.innerHTML='<p class="incorrect">Chưa đúng rồi. Đọc lại manh mối và thử một đáp án khác nhé!</p>';return;}
 quiz.done=true;const c=card(quiz.card),wasCompleted=completed(data,state,c.region),before=access(data,state);const added=award(data,state,c.id);save();button.classList.add('correct');const after=access(data,state);const newRegions=[...after.regions].filter(x=>!before.regions.has(x));const newChapters=[...after.chapters].filter(x=>!before.chapters.has(x));
 feedback.innerHTML=`<div class="reward"><span>${icon('check')}</span><h3>${added?'Bạn nhận được một thẻ mới!':'Bạn vẫn nhớ rất tốt!'}</h3><b>${esc(c.name)}</b><p>${esc(c.intro)}</p>${!wasCompleted&&completed(data,state,c.region)?`<p class="unlock-message">${newRegions.length?'Mở vùng: '+newRegions.map(x=>esc(byRegion(x).name)).join(', '):'Đã hoàn thành vùng '+esc(byRegion(c.region).name)}${newChapters.length?'<br>Mở chapter: '+newChapters.map(x=>esc(chapter(x).name)).join(', '):''}</p>`:''}<button class="primary wide" id="claim">${added?'Cất vào sổ':'Trở về sổ'} ${icon('book')}</button></div>`;document.querySelector('#claim').onclick=()=>{dialog.close();render();};document.querySelector('#claim').focus();}
function openHeritage(id){const h=data.heritages.find(x=>x.id===id);showDialog(`<span class="eyebrow">DI SẢN SỐNG · HỒ SƠ CHUNG</span><h2>${esc(h.name)}</h2><p>${esc(h.intro)}</p><p>Không gian liên quan trong bản thử: ${h.regions.map(x=>esc(byRegion(x)?.name||x)).join(', ')}.</p><p class="muted">Di sản phi vật thể là thực hành văn hóa của cộng đồng, không phải một địa điểm duy nhất. Danh sách vùng liên quan còn được bổ sung.</p><a href="${esc(h.source)}" target="_blank" rel="noopener noreferrer">Hồ sơ UNESCO ↗</a>`);}
function profile(){showDialog(`<span class="eyebrow">NHÀ THÁM HIỂM</span><h2>${esc(state.name)}</h2><p>${stats()}</p><p>Hồ sơ được lưu trên trình duyệt này. Xuất bản sao để chuyển sang thiết bị khác.</p><div class="profile-actions"><button id="export" class="primary">${icon('download')} Xuất tiến độ</button><label class="secondary import-label">Nhập tiến độ<input id="import" type="file" accept="application/json,.json" hidden></label><button id="new-game" class="text-button danger">Bắt đầu hành trình mới</button></div>`);
 document.querySelector('#export').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='so-viet-tien-do.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};document.querySelector('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>1e6){notify('Tệp tiến độ quá lớn.');return;}try{const next=restore(data,await file.text());if(!next)throw Error();state=next;region=state.lastRegion;save();dialog.close();render();notify('Đã khôi phục tiến độ.');}catch{notify('Tệp tiến độ không hợp lệ. Dữ liệu hiện tại vẫn được giữ.');}};
 document.querySelector('#new-game').onclick=()=>{showDialog(`<h2>Bắt đầu lại hành trình?</h2><p>Tiến độ hiện tại trên trình duyệt sẽ bị thay thế. Hãy xuất bản sao trước nếu muốn giữ lại.</p><button class="primary danger" id="confirm-reset">Xóa tiến độ và chọn lại</button>`);document.querySelector('#confirm-reset').onclick=()=>{try{localStorage.removeItem(KEY);}catch{}state=null;selectedStart='';view='book';dialog.close();render();};};}
function about(){showDialog(`<span class="eyebrow">SỔ VIỆT · BẢN CHƠI THỬ</span><h2>Một Việt Nam thật gần</h2><p>Bản đầu có 34 chapter, 63 vùng và ${data.cards.length} thẻ. Dữ liệu bản đồ được giản lược từ GeoJSON; các vùng trước sắp xếp được tái dựng bằng cách ghép phường/xã theo mã lịch sử.</p><p>12 thẻ đã có tranh hoạt hình tạo riêng. Các thẻ còn lại dùng biểu tượng tạm và thử thách bằng mô tả. Ảnh minh họa không thay thế ảnh tư liệu.</p><p>Giới thiệu là bản biên tập ngắn; nhiều nguồn Wikipedia đang là liên kết tham khảo, cần duyệt nội dung trước phát hành. Hồ sơ UNESCO dẫn nguồn chính thức. Bộ di sản phi vật thể đang được bổ sung, không coi bản thử là danh mục đầy đủ.</p><p>Hồ sơ lưu cục bộ, chưa có tài khoản máy chủ hoặc đồng bộ tự động.</p><a href="credits.html" target="_blank" rel="noopener">Nguồn dữ liệu và giấy phép ↗</a>`);}
function guide(){showDialog(`<span class="eyebrow">CÁCH CHƠI</span><h2>Mỗi thẻ, một điều mới</h2><ol class="guide-list"><li>Chọn thẻ chưa mở trong Địa danh hoặc Món ăn.</li><li>Giải câu đố để nhận thẻ. Sai có thể thử lại, thẻ không bị mất.</li><li>Đủ 3 thẻ khác nhau tại một vùng sẽ mở các vùng còn lại trong chapter.</li><li>Hoàn thành mọi vùng trong chapter để mở các chapter tiếp giáp.</li><li>Vào Tất cả để phóng to, kéo bản đồ và chọn nơi đi tiếp.</li></ol><p>Thành tựu tính trên toàn bộ hành trình. Nhấn kính lúp để tìm địa điểm hoặc đặc sản.</p>`);}
function bindGlobal(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=e=>{e.preventDefault();const action=b.dataset.action;if(action==='home'){if(state){view='book';render();}}if(action==='world'){view='world';zoom=1;pan=[0,0];render();}if(action==='book'){view='book';render();}if(action==='profile')profile();if(action==='about')about();if(action==='guide')guide();});}
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
try{const response=await fetch('./data.json');if(!response.ok)throw Error('Không tải được dữ liệu');data=await response.json();let raw=null;try{raw=localStorage.getItem(KEY);}catch{}state=raw?restore(data,raw):null;region=state?.lastRegion||data.regions[0].id;render();if(raw&&!state)notify('Bản lưu chưa hợp lệ. Bạn có thể tạo hành trình mới hoặc nhập bản sao.');}catch(error){app.innerHTML=`<main class="load-error"><h1>Chưa mở được sổ</h1><p>Kiểm tra kết nối rồi tải lại trang nhé.</p><button onclick="location.reload()">Thử lại</button></main>`;console.error(error);}
